(()=>{'use strict';const $=s=>document.querySelector(s);const toc=$('#toc'),overlay=$('#overlay'),toggle=$('#toc-toggle');function setToc(open){toc.hidden=!open;overlay.hidden=!open;toggle.setAttribute('aria-expanded',String(open));document.body.style.overflow=open?'hidden':'';if(open)$('#toc-close').focus();else toggle.focus()}toggle.onclick=()=>setToc(toc.hidden);$('#toc-close').onclick=()=>setToc(false);overlay.onclick=()=>setToc(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!toc.hidden)setToc(false);if(e.key==='Tab'&&!toc.hidden){const nodes=[...toc.querySelectorAll('a,button')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});toc.querySelectorAll('a').forEach(a=>a.onclick=()=>setToc(false));try{if(localStorage.getItem('sermon-theme')==='dark')document.body.classList.add('dark')}catch{}$('#theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('sermon-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};let size=0;$('#font').onclick=()=>{size=(size+1)%3;document.documentElement.style.setProperty('--size',[innerWidth<650?'17px':'18px','20px','22px'][size])};$('#print').onclick=()=>window.print();$('#focus').onclick=()=>{document.body.classList.toggle('focus');$('#focus').textContent=document.body.classList.contains('focus')?'退出专注':'专注阅读'};const update=()=>{const height=document.documentElement.scrollHeight-innerHeight;$('#progress').style.width=(height>0?scrollY/height*100:0)+'%'};addEventListener('scroll',update,{passive:true});addEventListener('resize',update);update();const io=new IntersectionObserver(items=>{items.forEach(x=>{if(x.isIntersecting){toc.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+x.target.id))}})},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('.chapter').forEach(s=>io.observe(s));$('#read-time').textContent='约 '+Math.ceil($('#article').textContent.length/380)+' 分钟 · 讲章 + 深入研读';document.querySelectorAll('.flash').forEach(b=>{const original=b.innerHTML;b.setAttribute('aria-pressed','false');b.onclick=()=>{const reveal=b.classList.toggle('revealed');b.setAttribute('aria-pressed',String(reveal));b.innerHTML=reveal?b.dataset.answer+'<span>再点一次收起</span>':original}});$('#answers').onclick=()=>{const list=[...document.querySelectorAll('.discussion')];const open=!list.every(x=>x.open);list.forEach(x=>x.open=open);$('#answers').textContent=open?'收起全部答案':'展开全部答案'};let queue=[],current=0,active=false;function stop(){active=false;queue=[];if('speechSynthesis'in window)speechSynthesis.cancel();$('#audio-status').textContent='朗读已停止'}function next(){if(!active||current>=queue.length){active=false;$('#audio-status').textContent='朗读完成';return}const u=new SpeechSynthesisUtterance(queue[current++]);u.lang='zh-CN';u.rate=.9;u.onend=next;u.onerror=()=>{active=false;$('#audio-status').textContent='设备朗读不可用，请检查系统中文语音。'};speechSynthesis.speak(u)}$('#speak').onclick=()=>{if(!('speechSynthesis'in window)){$('#audio-status').textContent='此浏览器不支持设备朗读。';return}speechSynthesis.cancel();queue=['why','how','result'].flatMap(id=>[...document.querySelectorAll('#'+id+' h2,#'+id+' p')].map(x=>x.textContent));current=0;active=true;$('#audio-status').textContent='正在使用设备语音朗读；可随时停止。';next()};$('#stop').onclick=stop;addEventListener('pagehide',()=>{if('speechSynthesis'in window)speechSynthesis.cancel()});addEventListener('beforeprint',()=>document.querySelectorAll('.discussion').forEach(x=>{x.dataset.wasOpen=String(x.open);x.open=true}));addEventListener('afterprint',()=>document.querySelectorAll('.discussion').forEach(x=>x.open=x.dataset.wasOpen==='true'));})();
